#include "metalrobo/DiscreteElasticRod.hpp"
#include "metalrobo/MetalDiscreteElasticRod.hpp"
#include <array>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>

using namespace metalrobo;
constexpr double L=.025,E=2.129e9,I=3.960e-12,area=3.449e-6,radius=.00185,density=1200,delta=.000025,dh=.00000001;
DiscreteElasticRodModel model(unsigned n){DiscreteRodMaterial mat{.radius=radius,.density=density,.youngModulus=E,.poissonRatio=.35};auto m=makeStraightSutureRod(n,L,mat);m.name="related_crow_rachis_energy_instrument";m.fidelityBoundary="uniform short-segment surrogate; carrion crow sample";std::fill(m.bendStiffness.begin(),m.bendStiffness.end(),E*I);std::fill(m.stretchStiffness.begin(),m.stretchStiffness.end(),E*area);double dm=density*area*L/(n-1);for(unsigned j=0;j<n;++j)m.nodeMasses[j]=(j==0||j==n-1)?.5*dm:dm;return m;}
DiscreteElasticRodState shaped(const DiscreteElasticRodModel&m,double d){auto s=makeDiscreteElasticRodDefaultState(m);for(auto& p:s.positions){double x=p[0]/L;if(x>.5)x=1-x;p[1]=d*(3*x-4*x*x*x);}return s;}
double energy(const DiscreteElasticRodModel&m,double d){auto s=shaped(m,d);DiscreteElasticRodEnergy e;auto diag=evaluateDiscreteElasticRodEnergy(m,s,e);if(!diag.succeeded())throw std::runtime_error("energy reference failed");return e.total();}
void stateJson(const DiscreteElasticRodState&s){std::cout<<"[";for(size_t i=0;i<s.positions.size();++i){if(i)std::cout<<',';std::cout<<'[';for(int j=0;j<3;++j)std::cout<<s.positions[i][j]<<',';for(int j=0;j<3;++j){if(j)std::cout<<',';std::cout<<s.velocities[i][j];}std::cout<<']';}std::cout<<']';}
int main(){try{std::cout<<std::setprecision(14);auto m=model(9);for(double tol:{1e-8,1e-10,1e-12}){auto s=shaped(m,delta);DiscreteElasticRodEnergy before;auto q=evaluateDiscreteElasticRodEnergy(m,s,before);if(!q.succeeded())throw std::runtime_error("initial energy failed");DiscreteElasticRodStepConfig cfg;cfg.timestep=.001;cfg.gravity={0,0,0};cfg.solverIterations=4096;cfg.constraintTolerance=tol;cfg.linearDamping=100;cfg.twistDamping=100;std::array<DiscreteRodAttachment,3> a{{{.nodeIndex=0,.targetPosition={0,0,0}},{.nodeIndex=4,.targetPosition={L/2,delta,0}},{.nodeIndex=8,.targetPosition={L,0,0}}}};std::array<DiscreteRodAttachmentReaction,3> r{};auto d=stepDiscreteElasticRodCpu(m,s,a,cfg,r);double kinetic=0;for(int i=0;i<9;++i)for(int j=0;j<3;++j)kinetic+=.5*m.nodeMasses[i]*s.velocities[i][j]*s.velocities[i][j];for(int i=0;i<8;++i)kinetic+=.5*m.edgeRotationalInertias[i]*s.twistRates[i]*s.twistRates[i];std::cout<<"{\"tolerance\":"<<tol<<",\"success\":"<<(d.succeeded()?"true":"false")<<",\"status\":"<<std::quoted(discreteElasticRodStatusName(d.status))<<",\"message\":"<<std::quoted(d.message)<<",\"iterations\":"<<d.iterations<<",\"before\":"<<before.total()<<",\"after\":"<<d.after.total()<<",\"kinetic\":"<<kinetic<<",\"reaction\":["<<r[0].averageForceOnTarget[1]<<','<<r[1].averageForceOnTarget[1]<<','<<r[2].averageForceOnTarget[1]<<"],\"node_forces\":[";for(int i=0;i<9;++i){auto p=s;double h=1e-9;p.positions[i][1]+=h;DiscreteElasticRodEnergy ep,em;if(!evaluateDiscreteElasticRodEnergy(m,p,ep).succeeded())throw std::runtime_error("plus failed");p.positions[i][1]-=2*h;if(!evaluateDiscreteElasticRodEnergy(m,p,em).succeeded())throw std::runtime_error("minus failed");if(i)std::cout<<',';std::cout<<-(ep.total()-em.total())/(2*h);}std::cout<<"],\"state\":";stateJson(s);std::cout<<",\"twists\":[";for(size_t i=0;i<s.twists.size();++i){if(i)std::cout<<',';std::cout<<'['<<s.twists[i]<<','<<s.twistRates[i]<<']';}std::cout<<"]}\n";}return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}